  SELECT tip_doc, key_value, cod_instit_financiera, flg_ibk, tipo_ingreso, nodo, pd_raw, flg_pd_raw, flg_calib, flg_clean, target_01m, target_02m, target_03m, target_04m, target_05m, target_06m, target_07m, target_08m, target_09m, target_10m, target_11m, target_12m, codmes,
         greatest(least(CAST(pd_raw AS double), 1 - 1e-06), 1e-06) AS p
  FROM disc_model_owner.ds_adm_tcbank_cal
),
cal AS (
  SELECT b.*, iso.y_lo + (iso.y_hi - iso.y_lo) * (b.p - iso.x_lo) / (iso.x_hi - iso.x_lo) AS pcal
  FROM base b
  LEFT JOIN coef_iso iso ON b.p >= iso.x_lo AND b.p < iso.x_hi
),
anch AS (
  SELECT c.*,
    CASE WHEN c.flg_clean = 0 THEN 0.1840689848 + (CASE WHEN c.nodo = 'NODO 3' AND c.codmes >= '202505' THEN 0.2385035485 ELSE 0.0 END)
         ELSE COALESCE(cc.delta, 0.0945542000) END AS delta,
    COALESCE(ft.ft, 0.0) AS ftv
  FROM cal c
  LEFT JOIN coef_celda cc ON cc.ak = c.tipo_ingreso || '|' || c.nodo
  LEFT JOIN coef_ft ft ON ft.codmes = c.codmes
),
scored AS (
  SELECT a.*,
    CASE WHEN a.pd_raw IS NULL THEN NULL ELSE
      normal_cdf(0, 1, (inverse_normal_cdf(0, 1, greatest(least(a.pcal, 1 - 1e-06), 1e-06)) + a.delta + (CASE WHEN a.flg_clean = 0 THEN 1.000000 ELSE 2.000000 END) * a.ftv) / 0.9832600000) END AS prob_c
  FROM anch a
)
SELECT
    a.tip_doc,
    a.key_value,
    a.cod_instit_financiera,
    a.flg_ibk,
    a.tipo_ingreso,
    a.nodo,
    a.pd_raw,
    a.flg_pd_raw,
    a.flg_calib,
    a.flg_clean,
    a.target_01m,
    a.target_02m,
    a.target_03m,
    a.target_04m,
    a.target_05m,
    a.target_06m,
    a.target_07m,
    a.target_08m,
    a.target_09m,
    a.target_10m,
    a.target_11m,
    a.target_12m,
    a.prob_c AS prob_modelo_cal,
    CASE WHEN a.prob_c IS NULL THEN NULL ELSE CAST(round(1000.0 * (1 - a.prob_c)) AS integer) END AS puntuacion_modelo_cal,
    a.codmes
FROM scored a